"use client";

import { useState, useRef, useEffect } from "react";
import Message from "./Message";
import Header from "./Header";
import { Smile, Send, Paperclip, X } from "lucide-react";
import { Picker } from "ms-3d-emoji-picker";
import { PlaceholdersAndVanishInput } from "@/components/ui/placeholders-and-vanish-input";
import { motion, AnimatePresence } from "framer-motion";
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";
import isToday from "dayjs/plugin/isToday";
import isYesterday from "dayjs/plugin/isYesterday";
import { useSidebar } from "../Context/context";

dayjs.extend(relativeTime);
dayjs.extend(isToday);
dayjs.extend(isYesterday);

const ChatWindow = ({ conversation, messages: initialMessages }) => {
  const [messages, setMessages] = useState(initialMessages);
  const [message, setMessage] = useState("");
  const [showPicker, setShowPicker] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const messagesEndRef = useRef(null);
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSend = () => {
    if (message.trim()) {
      const newMessage = {
        id: messages.length + 1,
        text: message,
        sender: "sender",
        time: dayjs().format("h:mm A"),
        date: dayjs().format("YYYY-MM-DD"),
        conversationId: conversation.id,
      };
      setMessages([...messages, newMessage]);
      setMessage("");
    }
  };

  return (
    <div className="flex h-screen bg-zinc-900">
      <div className={`flex flex-col flex-1 ${sidebarOpen ? "lg:w-2/3" : "w-full"}`}>        
        <Header conversation={conversation} onAvatarClick={() => setSidebarOpen(true)} />
        <div className="flex-1 overflow-y-auto p-4">
          {messages.map((msg) => (
            <Message key={msg.id} message={msg} isOwnMessage={msg.sender === "sender"} />
          ))}
          <div ref={messagesEndRef} />
        </div>
        <div className="border-t p-4 bg-zinc-900 flex items-center gap-3 relative">
          <button onClick={() => setShowPicker(!showPicker)} className="p-2 hover:bg-zinc-700 rounded-lg">
            <Smile className="w-6 h-6 text-gray-400" />
          </button>
          {showPicker && (
            <div className="absolute bottom-16 left-4">
              <Picker onEmojiClick={(emoji) => setMessage((prev) => prev + emoji.native)} />
            </div>
          )}
          <div className="flex-1">
            <PlaceholdersAndVanishInput placeholders={["Type a message..."]} onChange={(e) => setMessage(e.target.value)} onSubmit={handleSend} value={message} />
          </div>
          <button onClick={handleSend} className="p-2 hover:bg-zinc-700 rounded-lg">
            <Send className="w-6 h-6 text-blue-500" />
          </button>
        </div>
      </div>
      {sidebarOpen && (
        <div className="w-1/3 bg-zinc-800 p-6 shadow-lg border-l border-gray-700 relative">
          <button onClick={() => setSidebarOpen(false)} className="absolute top-4 right-4">
            <X className="w-6 h-6 text-gray-400" />
          </button>
        </div>
      )}
    </div>
  );
};

export default ChatWindow;
